#include <stdio.h>

/* teste do desafio a-virada — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Este e o desafio da VIRADA: os tres fatos no MESMO arquivo — uma caixa
   devolve, a outra imprime, e chamar a que devolve sozinha nao imprime.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout para
   um arquivo temporario e fflush descarrega SEM fechar — o stdout precisa
   ficar aberto para o segundo freopen do cenario 3. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int dobro(int n);
void mostrarDobro(int n);

/* cenario 1 — DEVOLVE: so o retorno, sem captura nenhuma */
SM_TEST(o_dobro_devolve_o_valor) {
    checa_int("o dobro de 2 e 4", dobro(2), 4,
              "o dobro de n e n vezes 2");
    checa_int("o dobro de 7 e 14", dobro(7), 14,
              "a caixa calcula com o valor recebido: nao devolve um numero fixo");
}

/* cenario 2 — IMPRIME: captura 1, com DOIS valores (um texto fixo na tela
   passaria com um valor so) e a prova do FIM da saida */
SM_TEST(mostrar_dobro_imprime_a_linha) {
    freopen("sm_saida_1.tmp", "w", stdout);
    mostrarDobro(2);
    mostrarDobro(7);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do dobro de 2", linha, "o dobro de 2 e 4\n",
              "mostrarDobro escreve a frase com o valor recebido e o dobro dele");
    fgets(linha, 80, f);
    checa_str("a linha do dobro de 7", linha, "o dobro de 7 e 14\n",
              "a MESMA caixa com 7: os dois numeros mudam junto, nada e fixo");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "cada chamada imprime UMA linha: a saida acaba na segunda");
    fclose(f);
}

/* cenario 3 — CHAMAR SOZINHA NAO IMPRIME: captura 2 no MESMO desafio */
SM_TEST(chamar_o_dobro_sozinho_nao_imprime) {
    freopen("sm_saida_2.tmp", "w", stdout);
    dobro(2);            /* chama e descarta o valor: nenhum printf roda */
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("chamar sozinha nao imprime", linha, "(nada impresso)",
              "dobro devolve um valor; imprimir e o outro canal");
    fclose(f);
}

